sys_ws_operation.operation_script:
// RBAC Authorization Check
var __authorized = (function() {
  if (gs.hasRole("admin")) return true;
  var roles = "x_2056099_indust_0.production_planner,x_2056099_indust_0.production_manager,x_2056099_indust_0.plant_manager,x_2056099_indust_0.operations_manager".split(",");
  for (var _i = 0; _i < roles.length; _i++) {
    if (gs.hasRole(roles[_i])) return true;
  }
  response.setStatus(403);
  response.setBody({error:"Unauthorized",message:"Insufficient role for this operation"});
  return false;
})();
if (!__authorized) { /* early exit */ }
else
(function process(request, response) {
  var body = {};
  try { body = JSON.parse(request.body.dataString); } catch (e) {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "Invalid request body" } });
    return;
  }

  // Handle Action = Apply Proposal
  // [HackNow critical features] apply a stored proposal (all its schedule/order changes) by scenario
  if (body.action === "apply" && body.scenario_sys_id) {
    var applied = new x_2056099_indust_0.AdaptiveRescheduler().applyScenario(body.scenario_sys_id);
    if (!applied.success) { response.setStatus(400); }
    response.setBody({ result: applied });
    return;
  }
  if (body.action === "apply") {
    var applyEngine = new x_2056099_indust_0.WhatIfSimulationEngine();
    var applyResult = applyEngine.applyProposal(body);
    if (!applyResult.success) {
      response.setStatus(400);
    }
    response.setBody({ result: applyResult });
    return;
  }

  if (!body.scenario_type) {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "scenario_type is required. Supported: resource_down, capacity_reduction, quantity_change, material_shortage, schedule_shift" } });
    return;
  }

  var engine = new x_2056099_indust_0.WhatIfSimulationEngine();
  var result = engine.simulate(body);

  if (!result.success) {
    response.setStatus(400);
  }
  response.setBody({ result: result });
})(request, response);
